package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class JsonWriter_value_TriageGen0Test {

    private StringWriter out;
    private JsonWriter jsonWriter;

    @Before
    public void setUp() {
        out = new StringWriter();
        jsonWriter = new JsonWriter(out);
    }









    @Test
    public void testValue_NonFinite_StrictMode_ThrowsException() {
        // Testing "Infinity"
        try {
            jsonWriter.value(Double.POSITIVE_INFINITY);
            org.junit.Assert.fail("Should have thrown IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Numeric values must be finite"));
        } catch (IOException e) {
            org.junit.Assert.fail("IOException should not be thrown");
        }

        // Testing "-Infinity"
        try {
            jsonWriter.value(Double.NEGATIVE_INFINITY);
            org.junit.Assert.fail("Should have thrown IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Numeric values must be finite"));
        } catch (IOException e) {
            org.junit.Assert.fail("IOException should not be thrown");
        }

        // Testing "NaN"
        try {
            jsonWriter.value(Double.NaN);
            org.junit.Assert.fail("Should have thrown IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Numeric values must be finite"));
        } catch (IOException e) {
            org.junit.Assert.fail("IOException should not be thrown");
        }
    }




}

package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class JsonWriter_value_TriageGen0Test {

    private StringWriter out;
    private JsonWriter jsonWriter;

    @Before
    public void setUp() {
        out = new StringWriter();
        jsonWriter = new JsonWriter(out);
    }











    @Test
    public void testValue_NonFinite_LenientMode_Success() throws IOException {
        jsonWriter.setLenient(true);

        jsonWriter.value(Double.POSITIVE_INFINITY);
        assertEquals("Infinity", out.toString());

        out.getBuffer().setLength(0);
        jsonWriter.value(Double.NEGATIVE_INFINITY);
        assertEquals("-Infinity", out.toString());

        out.getBuffer().setLength(0);
        jsonWriter.value(Double.NaN);
        assertEquals("NaN", out.toString());
    }


}

